const biopaySpecYaml = "# BioPay — DRAFT OpenAPI document for the third-party-facing surface.\r\n#\r\n# Every operation here is consumed by the authorised initiator (ICP, holding the\r\n# BPIP role) against the API Hub, with one exception: the registration event,\r\n# which the Hub POSTs to an endpoint ICP implements. Direction is stated in each\r\n# operation description.\r\n#\r\n# One call in this journey is LFI → API Hub and deliberately NOT modelled here\r\n# (see the third-party-facing-only scoping decision):\r\n#   - the LFI posting a completed registration to the Hub\r\n# It is described in prose on /biopay/technical-architecture.\r\n#\r\n# The other LFI → API Hub call, PATCH /biometrics-payment-log/{id}, IS\r\n# modelled: it is how the payment status the initiator polls and is notified of\r\n# comes to exist, so the third-party-facing surface cannot be read without it.\r\n# It is served at the Consent Manager host, not at the rs1.* host the rest of\r\n# this document uses.\r\n#\r\n# Nothing in this document is published. Field names, enum values, endpoint\r\n# paths and status vocabulary are all proposals for review. The status values\r\n# align with the published payments standard (Pending / AcceptedWithoutPosting /\r\n# Accepted / Rejected) so BioPay does not invent a second vocabulary.\r\n#\r\n# Discovery follows the same pattern as the published Confirmation of Payee\r\n# /discovery operation: a POST whose request and response are both signed JWTs\r\n# (application/jwt), returning DiscoveryEndpointUrl and ResourceServerUrl for\r\n# the LFI that holds the registration.\r\n#\r\n# The registration event follows the published webhook template: the same signed\r\n# envelope, the same Data/Meta split under the message claim, the same\r\n# Resource.Created/Updated/Deleted event types, delivered as application/jwe.\r\n# Its Data is the discovery Data, so the event and discovery describe a\r\n# registration identically.\r\n#\r\n# The payment operations still use unsigned JSON with a detached\r\n# x-jws-signature header; whether they should move to the same signed-body\r\n# pattern is an open item.\r\n\r\nopenapi: 3.0.3\r\n\r\ninfo:\r\n  title: BioPay — Biometric Payments (draft)\r\n  version: 0.1.0-draft\r\n  description: >-\r\n    Draft third-party-facing API for BioPay: a payment journey in which a\r\n    customer is identified biometrically by ICP, and ICP — as a specifically\r\n    authorised initiator — initiates a payment through the API Hub under a\r\n    `client_credentials` grant. No biometric, template or match score crosses\r\n    into Open Finance. What crosses is an ICP user identifier and ICP's\r\n    assertion that it identified the person.\r\n\r\nservers:\r\n  - url: https://rs1.[LFICODE].apihub.openfinance.ae/open-finance/biometric-payments/v1\r\n    description: Production\r\n  - url: https://rs1.[LFICODE].preprod.apihub.openfinance.ae/open-finance/biometric-payments/v1\r\n    description: Pre-production\r\n  - url: https://rs1.altareq1.sandbox.apihub.openfinance.ae/open-finance/biometric-payments/v1\r\n    description: Sandbox\r\n\r\ntags:\r\n  - name: Registration\r\n    description: Querying and being notified about a customer's BioPay registration.\r\n  - name: Payment\r\n    description: Initiating a biometric payment and tracking its status.\r\n  - name: Payment log\r\n    description: >-\r\n      Reporting the outcome of a biometric payment. Called by the LFI, not by\r\n      the initiator.\r\n\r\npaths:\r\n  # ═════════════════════════════════════════════════════════════════════════\r\n  # REGISTRATION\r\n  # ═════════════════════════════════════════════════════════════════════════\r\n  /biometric-payments-discovery:\r\n    post:\r\n      tags: [Registration]\r\n      operationId: postBiometricPaymentsDiscovery\r\n      summary: Discover a customer's BioPay registration\r\n      description: >-\r\n        **ICP → API Hub.** Resolves an ICP user identifier to the registration\r\n        the API Hub holds for it: whether that registration is live, which\r\n        payment instrument(s) the customer selected, and the endpoints at which\r\n        the initiator obtains a token for — and then calls — the LFI holding it.\r\n        Answered by the API Hub from its own registration store; this call is\r\n        **not** proxied to the LFI.\r\n\r\n\r\n        Modelled on the published Confirmation of Payee `/discovery` operation,\r\n        so that BioPay does not introduce a second discovery pattern. The\r\n        request is a signed JWT whose `message` carries the identifier to\r\n        resolve; the response is a signed JWT whose `message` carries the\r\n        resolved registration and routing. Both directions are\r\n        `application/jwt`, and the signature **is** the JWT — this operation\r\n        carries no detached `x-jws-signature` header.\r\n\r\n\r\n        Signing the request is also what allows the identifier to travel in a\r\n        body rather than a query string, keeping it out of access and proxy\r\n        logs. That is why this operation is a `POST`; the earlier draft modelled\r\n        it as a `GET` with an `IcpUserId` query parameter and flagged the\r\n        logging exposure as an open item.\r\n\r\n\r\n        The initiator MUST call this before initiating a payment: a registration\r\n        may have been suspended, revoked, or had its default instrument changed\r\n        since the registration event was received. The initiator MUST address\r\n        the payment call using the `ResourceServerUrl` returned here rather than\r\n        a URL it derived itself.\r\n\r\n\r\n        The registration event carries this same `Data`, so an initiator\r\n        already holds the routing before it calls discovery. That overlap is\r\n        deliberate and matches CoP: the event is how routing arrives, and\r\n        discovery is how it is confirmed still current at the moment of\r\n        payment. Open item: whether discovery should be callable at any\r\n        LFI-scoped host, as CoP allows, rather than only at the host the\r\n        registration resolved to.\r\n      parameters:\r\n        - $ref: '#/components/parameters/XFapiInteractionId'\r\n        - $ref: '#/components/parameters/XFapiAuthDate'\r\n      requestBody:\r\n        required: true\r\n        content:\r\n          application/jwt:\r\n            schema:\r\n              $ref: '#/components/schemas/DiscoverBiometricRegistrationRequestBodySigned'\r\n      responses:\r\n        '200':\r\n          description: >-\r\n            The registration state held by the API Hub, as a signed JWT. A `200`\r\n            is returned for an unregistered identifier too, with\r\n            `RegistrationStatus` set to `NotRegistered` and the routing fields\r\n            absent — absence of a registration is a fact, not an error.\r\n          headers:\r\n            x-fapi-interaction-id:\r\n              $ref: '#/components/headers/XFapiInteractionId'\r\n          content:\r\n            application/jwt:\r\n              schema:\r\n                $ref: '#/components/schemas/DiscoverBiometricRegistrationResponseBodySigned'\r\n        '400':\r\n          description: >-\r\n            The request was malformed or failed schema validation. A request\r\n            whose JWT cannot be verified is reported with the signing error\r\n            codes the Confirmation of Payee standard already defines —\r\n            `JWS.InvalidSignature`, `JWS.Malformed`, `JWS.InvalidClaim`,\r\n            `JWS.InvalidHeader` — rather than a BioPay-specific set.\r\n          headers:\r\n            x-fapi-interaction-id:\r\n              $ref: '#/components/headers/XFapiInteractionId'\r\n          content:\r\n            application/jwt:\r\n              schema:\r\n                $ref: '#/components/schemas/AEErrorResponseBodySigned'\r\n        '401': { $ref: '#/components/responses/Unauthorized' }\r\n        '403':\r\n          description: >-\r\n            The client is authenticated but not entitled — typically a client\r\n            whose application does not carry the BPIP role, or a token without\r\n            the `biometric-payments` scope.\r\n          headers:\r\n            x-fapi-interaction-id:\r\n              $ref: '#/components/headers/XFapiInteractionId'\r\n          content:\r\n            application/jwt:\r\n              schema:\r\n                $ref: '#/components/schemas/AEErrorResponseBodySigned'\r\n        '429': { $ref: '#/components/responses/TooManyRequests' }\r\n        '500':\r\n          description: An unexpected error occurred at the API Hub.\r\n          headers:\r\n            x-fapi-interaction-id:\r\n              $ref: '#/components/headers/XFapiInteractionId'\r\n          content:\r\n            application/jwt:\r\n              schema:\r\n                $ref: '#/components/schemas/AEErrorResponseBodySigned'\r\n\r\n  /biometric-payment-registration-events:\r\n    post:\r\n      tags: [Registration]\r\n      operationId: postBiometricPaymentRegistrationEvent\r\n      summary: Registration event notification\r\n      description: >-\r\n        **API Hub → ICP.** The Hub delivers this event to the endpoint ICP\r\n        registered in the Directory, after an LFI has posted a completed\r\n        registration to the Hub. This is the mechanism by which ICP learns that\r\n        an identity has a payment capability, **and where to address** that\r\n        identity's subsequent discovery and payment calls.\r\n\r\n\r\n        The path shown is illustrative — the real target is ICP's registered\r\n        event endpoint.\r\n\r\n\r\n        Structured as an Open Finance webhook, not as a BioPay-specific\r\n        notification. The envelope, the `message` claim, and the `Data` / `Meta`\r\n        split are those of the published webhook template used by the payment\r\n        status, consent status and insurance status events; `EventType` uses the\r\n        same `Resource.Created` / `Resource.Updated` / `Resource.Deleted`\r\n        vocabulary rather than a BioPay-specific one. A suspension or revocation\r\n        is therefore a `Resource.Updated` carrying the new `RegistrationStatus`\r\n        in `Data`, not a distinct event type.\r\n\r\n\r\n        `Data` carries the same schema the discovery operation returns, per the\r\n        webhook convention that the `Data` object holds the resource that\r\n        triggered the event. An initiator that processes this event holds\r\n        everything discovery would tell it — including\r\n        `DiscoveryEndpointUrl` and `ResourceServerUrl` — and still MUST call\r\n        discovery before initiating a payment, to confirm the registration has\r\n        not changed since.\r\n\r\n\r\n        Open items: the published webhook `Meta` carries no event identifier, so\r\n        de-duplication of retried deliveries rests on `RegistrationId` and\r\n        `EventDateTime` — the earlier draft carried an `EventId` for this. And\r\n        whether a revoked registration is reported as `Resource.Updated` with\r\n        `RegistrationStatus: Revoked` or as `Resource.Deleted` with `Data`\r\n        omitted is for review; both are expressible here.\r\n      requestBody:\r\n        required: true\r\n        content:\r\n          application/json:\r\n            schema:\r\n              $ref: '#/components/schemas/AEBiometricRegistrationEventSigned'\r\n          application/jwe:\r\n            schema:\r\n              type: string\r\n        description: >-\r\n          As with every other Open Finance webhook, the `application/json`\r\n          Content Type is provided so the initiator can understand the payload it\r\n          must parse; it does not reflect the wire format. The event is delivered\r\n          as a serialised, signed and encrypted JWT with the Content Type\r\n          `application/jwe`, signed by the API Hub and encrypted to the\r\n          initiator's encryption certificate registered in the Trust Framework.\r\n      responses:\r\n        '202':\r\n          description: >-\r\n            Accepted. The initiator MUST acknowledge on receipt, with an empty\r\n            body, and process asynchronously. The Hub retries on any non-2xx.\r\n          headers:\r\n            x-fapi-interaction-id:\r\n              $ref: '#/components/headers/XFapiInteractionId'\r\n        '204':\r\n          description: No content. Accepted on the same terms as `202`.\r\n          headers:\r\n            x-fapi-interaction-id:\r\n              $ref: '#/components/headers/XFapiInteractionId'\r\n        '400': { $ref: '#/components/responses/BadRequest' }\r\n        '401': { $ref: '#/components/responses/Unauthorized' }\r\n\r\n\r\n  # ═════════════════════════════════════════════════════════════════════════\r\n  # PAYMENT\r\n  # ═════════════════════════════════════════════════════════════════════════\r\n  /biometric-payments:\r\n    post:\r\n      tags: [Payment]\r\n      operationId: createBiometricPayment\r\n      summary: Initiate a biometric payment\r\n      description: >-\r\n        **ICP → API Hub → LFI.** Initiates a payment against a registered\r\n        customer. There is no consent resource and no access-token subject: the\r\n        customer's authority was established once, at registration, and is held\r\n        by the API Hub. The Hub resolves the LFI from the registration record,\r\n        validates the request against the schema for the named\r\n        `PaymentInstrument`, and proxies to that LFI's Ozone Connect.\r\n\r\n\r\n        The response is always `201` with `Status: Pending`. Execution on the\r\n        rail is asynchronous; the LFI patches status to the Hub, which notifies\r\n        the initiator and serves the updated resource on the GET operations.\r\n      parameters:\r\n        - $ref: '#/components/parameters/XIdempotencyKey'\r\n        - $ref: '#/components/parameters/XJwsSignature'\r\n        - $ref: '#/components/parameters/XFapiInteractionId'\r\n        - $ref: '#/components/parameters/XFapiAuthDate'\r\n      requestBody:\r\n        required: true\r\n        content:\r\n          application/json:\r\n            schema:\r\n              $ref: '#/components/schemas/AEBiometricPaymentRequest'\r\n      responses:\r\n        '201':\r\n          description: >-\r\n            Payment accepted for execution. A replay of the same\r\n            `x-idempotency-key` with an identical body returns the original\r\n            resource and this same `201`, not a duplicate payment.\r\n          headers:\r\n            x-fapi-interaction-id:\r\n              $ref: '#/components/headers/XFapiInteractionId'\r\n          content:\r\n            application/json:\r\n              schema:\r\n                $ref: '#/components/schemas/AEBiometricPaymentResponse'\r\n        '400': { $ref: '#/components/responses/BadRequest' }\r\n        '401': { $ref: '#/components/responses/Unauthorized' }\r\n        '403': { $ref: '#/components/responses/Forbidden' }\r\n        '409':\r\n          description: >-\r\n            The `x-idempotency-key` has already been used with a different\r\n            request body.\r\n          content:\r\n            application/json:\r\n              schema:\r\n                $ref: '#/components/schemas/AEErrorResponse'\r\n        '429': { $ref: '#/components/responses/TooManyRequests' }\r\n        '500': { $ref: '#/components/responses/InternalServerError' }\r\n\r\n    get:\r\n      tags: [Payment]\r\n      operationId: getBiometricPaymentByIdempotencyKey\r\n      summary: Retrieve a payment by idempotency key\r\n      description: >-\r\n        **ICP → API Hub.** Retrieves a payment by the `IdempotencyKey` the\r\n        initiator supplied when creating it. This is the recovery path for a lost\r\n        `201`: when the initiator does not know whether a payment was created, it\r\n        queries by the key it generated rather than initiating again.\r\n\r\n\r\n        Returns the single matching payment. When no payment exists for the key,\r\n        the response is `200` with an empty `Data` array — the initiator can then\r\n        safely retry the original request.\r\n      parameters:\r\n        - $ref: '#/components/parameters/IdempotencyKeyQuery'\r\n        - $ref: '#/components/parameters/XFapiInteractionId'\r\n        - $ref: '#/components/parameters/XFapiAuthDate'\r\n      responses:\r\n        '200':\r\n          description: Zero or one matching payment.\r\n          headers:\r\n            x-fapi-interaction-id:\r\n              $ref: '#/components/headers/XFapiInteractionId'\r\n          content:\r\n            application/json:\r\n              schema:\r\n                $ref: '#/components/schemas/AEBiometricPaymentQueryResponse'\r\n        '400': { $ref: '#/components/responses/BadRequest' }\r\n        '401': { $ref: '#/components/responses/Unauthorized' }\r\n        '403': { $ref: '#/components/responses/Forbidden' }\r\n        '429': { $ref: '#/components/responses/TooManyRequests' }\r\n        '500': { $ref: '#/components/responses/InternalServerError' }\r\n\r\n  /biometric-payments/{PaymentId}:\r\n    get:\r\n      tags: [Payment]\r\n      operationId: getBiometricPayment\r\n      summary: Retrieve a payment by PaymentId\r\n      description: >-\r\n        **ICP → API Hub.** Returns the current state of a payment. The API Hub\r\n        serves the status it holds, last set by the LFI. Polling this operation\r\n        is the pull alternative to the status webhook; an initiator MAY use\r\n        either or both.\r\n      parameters:\r\n        - $ref: '#/components/parameters/PaymentIdPath'\r\n        - $ref: '#/components/parameters/XFapiInteractionId'\r\n        - $ref: '#/components/parameters/XFapiAuthDate'\r\n      responses:\r\n        '200':\r\n          description: The payment resource.\r\n          headers:\r\n            x-fapi-interaction-id:\r\n              $ref: '#/components/headers/XFapiInteractionId'\r\n          content:\r\n            application/json:\r\n              schema:\r\n                $ref: '#/components/schemas/AEBiometricPaymentResponse'\r\n        '400': { $ref: '#/components/responses/BadRequest' }\r\n        '401': { $ref: '#/components/responses/Unauthorized' }\r\n        '403': { $ref: '#/components/responses/Forbidden' }\r\n        '404':\r\n          description: No payment exists with this `PaymentId` for this initiator.\r\n          content:\r\n            application/json:\r\n              schema:\r\n                $ref: '#/components/schemas/AEErrorResponse'\r\n        '429': { $ref: '#/components/responses/TooManyRequests' }\r\n        '500': { $ref: '#/components/responses/InternalServerError' }\r\n\r\n  # ══════════════════════════════════════════════════════════════════════════\r\n  # PAYMENT LOG — LFI → API Hub\r\n  # ══════════════════════════════════════════════════════════════════════════\r\n  # Served at the Consent Manager host (cm.{lfiCode}), not the rs1.* host the\r\n  # operations above use. Modelled on the published Consent Manager operation\r\n  # PATCH /payment-log/{id}, which is how an LFI reports the outcome of every\r\n  # other Open Finance payment.\r\n  /biometrics-payment-log/{id}:\r\n    patch:\r\n      tags: [Payment log]\r\n      operationId: patchBiometricPaymentLog\r\n      summary: Report the outcome of a biometric payment\r\n      description: >-\r\n        **LFI → API Hub.** Sets the status the API Hub holds for a biometric\r\n        payment once the LFI knows how the rail responded. The Hub is the\r\n        source of truth for payment state, and this is the only way that state\r\n        changes after creation: nothing the initiator calls can move a payment\r\n        out of `Pending`.\r\n\r\n\r\n        Every biometric payment is created `Pending` and the LFI MUST patch it\r\n        to a terminal status. One patch is the normal case — straight to\r\n        `Accepted`, `AcceptedWithoutPosting` or `Rejected`. An LFI MAY patch\r\n        more than once where the rail reports progress in stages, but MUST NOT\r\n        patch a payment that has already reached a terminal status.\r\n\r\n\r\n        The patch is what produces everything the initiator sees afterwards:\r\n        the Hub records the new status, delivers the payment status event to\r\n        the initiator's registered event endpoint, and serves the updated\r\n        resource on `GET /biometric-payments/{PaymentId}` and\r\n        `GET /biometric-payments`. An LFI that executes the payment but never\r\n        patches leaves the initiator polling a payment that stays `Pending`\r\n        forever.\r\n\r\n\r\n        Modelled on the published Consent Manager operation\r\n        `PATCH /payment-log/{id}`, and served at the same Consent Manager host,\r\n        so an LFI already integrated with Open Finance is patching biometric\r\n        payments the same way and from the same place as every other payment.\r\n\r\n\r\n        Open items: the published operation names its fields in the dotted,\r\n        lower-camel form `paymentResponse.status`, whereas this draft uses the\r\n        flat PascalCase names the rest of the BioPay document uses — which\r\n        convention wins is for review. And whether BioPay should reuse\r\n        `PATCH /payment-log/{id}` outright rather than introduce a second\r\n        payment log is open; it is modelled separately here because a biometric\r\n        payment has no consent, and the published payment log is keyed to one.\r\n      parameters:\r\n        - $ref: '#/components/parameters/PaymentIdLogPath'\r\n        - $ref: '#/components/parameters/XFapiInteractionId'\r\n      requestBody:\r\n        required: true\r\n        description: >-\r\n          The fields to set. Flat rather than `Data`-wrapped, following the\r\n          published Consent Manager patch operations rather than the\r\n          third-party-facing convention used elsewhere in this document.\r\n        content:\r\n          application/json:\r\n            schema:\r\n              $ref: '#/components/schemas/AEBiometricPaymentLogPatch'\r\n      responses:\r\n        '204':\r\n          description: >-\r\n            The status was recorded. No body. Delivery of the payment status\r\n            event to the initiator happens asynchronously and its outcome does\r\n            not affect this response — a `204` means the Hub holds the new\r\n            status, not that the initiator has received it.\r\n          headers:\r\n            x-fapi-interaction-id:\r\n              $ref: '#/components/headers/XFapiInteractionId'\r\n        '400': { $ref: '#/components/responses/BadRequest' }\r\n        '401': { $ref: '#/components/responses/Unauthorized' }\r\n        '403':\r\n          description: >-\r\n            The authenticated LFI does not hold the payment identified by\r\n            `id`.\r\n          content:\r\n            application/json:\r\n              schema:\r\n                $ref: '#/components/schemas/AEErrorResponse'\r\n        '404':\r\n          description: No payment exists with this `id`.\r\n          content:\r\n            application/json:\r\n              schema:\r\n                $ref: '#/components/schemas/AEErrorResponse'\r\n        '409':\r\n          description: >-\r\n            The payment has already reached a terminal status, and the\r\n            requested transition is not permitted.\r\n          content:\r\n            application/json:\r\n              schema:\r\n                $ref: '#/components/schemas/AEErrorResponse'\r\n        '500': { $ref: '#/components/responses/InternalServerError' }\r\n\r\ncomponents:\r\n  # ── Parameters ───────────────────────────────────────────────────────────\r\n  parameters:\r\n    IdempotencyKeyQuery:\r\n      name: IdempotencyKey\r\n      in: query\r\n      required: true\r\n      description: >-\r\n        The value the initiator sent in `x-idempotency-key` when creating the\r\n        payment.\r\n      schema:\r\n        type: string\r\n        maxLength: 40\r\n    PaymentIdPath:\r\n      name: PaymentId\r\n      in: path\r\n      required: true\r\n      description: The API Hub's identifier for the payment.\r\n      schema:\r\n        type: string\r\n        maxLength: 40\r\n    PaymentIdLogPath:\r\n      name: id\r\n      in: path\r\n      required: true\r\n      description: >-\r\n        The API Hub's identifier for the payment — the `PaymentId` the\r\n        initiator was returned on creation. Named `id` rather than `PaymentId`\r\n        to match the published Consent Manager operation\r\n        `PATCH /payment-log/{id}`, which this one sits alongside.\r\n      schema:\r\n        type: string\r\n        maxLength: 40\r\n    XIdempotencyKey:\r\n      name: x-idempotency-key\r\n      in: header\r\n      required: true\r\n      description: >-\r\n        Initiator-generated key that makes payment creation safely retryable.\r\n        MUST be unique per payment and retained by the initiator long enough to\r\n        support recovery via `GET /biometric-payments`.\r\n      schema:\r\n        type: string\r\n        maxLength: 40\r\n    XJwsSignature:\r\n      name: x-jws-signature\r\n      in: header\r\n      required: true\r\n      description: Detached JWS signature over the request body.\r\n      schema:\r\n        type: string\r\n    XFapiInteractionId:\r\n      name: x-fapi-interaction-id\r\n      in: header\r\n      required: false\r\n      description: Correlation identifier, echoed on the response.\r\n      schema:\r\n        type: string\r\n        format: uuid\r\n    XFapiAuthDate:\r\n      name: x-fapi-auth-date\r\n      in: header\r\n      required: false\r\n      description: >-\r\n        The time of the biometric identification at ICP, in HTTP-date format.\r\n      schema:\r\n        type: string\r\n\r\n  headers:\r\n    XFapiInteractionId:\r\n      description: Correlation identifier echoed from the request, or generated by the Hub.\r\n      schema:\r\n        type: string\r\n        format: uuid\r\n\r\n  # ── Responses ────────────────────────────────────────────────────────────\r\n  responses:\r\n    BadRequest:\r\n      description: The request was malformed or failed schema validation.\r\n      content:\r\n        application/json:\r\n          schema:\r\n            $ref: '#/components/schemas/AEErrorResponse'\r\n    Unauthorized:\r\n      description: The access token is missing, expired or invalid.\r\n    Forbidden:\r\n      description: >-\r\n        The client is authenticated but not entitled — typically a client whose\r\n        application does not carry the BPIP role, or a token without the\r\n        `biometric-payments` scope.\r\n      content:\r\n        application/json:\r\n          schema:\r\n            $ref: '#/components/schemas/AEErrorResponse'\r\n    TooManyRequests:\r\n      description: Rate limit exceeded.\r\n    InternalServerError:\r\n      description: An unexpected error occurred at the API Hub or the LFI.\r\n      content:\r\n        application/json:\r\n          schema:\r\n            $ref: '#/components/schemas/AEErrorResponse'\r\n\r\n  # ── Schemas ──────────────────────────────────────────────────────────────\r\n  schemas:\r\n    AEIcpUserId:\r\n      type: string\r\n      description: >-\r\n        The identifier ICP issues for a verified identity, and the only\r\n        identity-bearing value that crosses into Open Finance in this journey.\r\n        Format to be confirmed.\r\n      maxLength: 70\r\n      example: ICP-7c9e1f4a-2b60-4d3e-9a15-0f8c2d1b7e43\r\n\r\n    AEPaymentInstrument:\r\n      type: string\r\n      description: >-\r\n        The payment vehicle the customer selected at registration. Determines\r\n        which creditor schema the payment request MUST use. `JAYWAN` is the\r\n        domestic card scheme (referred to as J1 elsewhere) — the final code is\r\n        an open item.\r\n      enum: [AANI, CBDC, JAYWAN]\r\n\r\n    AERegistrationStatus:\r\n      type: string\r\n      description: >-\r\n        `NotRegistered` means the Hub holds no registration for the identifier.\r\n        `Suspended` means a registration exists but MUST NOT be used to initiate\r\n        a payment.\r\n      enum: [Registered, Suspended, Revoked, NotRegistered]\r\n\r\n    AEPaymentStatus:\r\n      type: string\r\n      description: >-\r\n        Aligned with the published payments standard rather than a\r\n        BioPay-specific vocabulary. `Pending` on creation; the LFI moves it as\r\n        the rail responds.\r\n      enum: [Pending, AcceptedWithoutPosting, Accepted, Rejected]\r\n\r\n    AEBiometricDiscoveryRequest:\r\n      type: object\r\n      description: >-\r\n        The `message` of the signed discovery request. Carries only the\r\n        identifier to resolve — the counterpart of the creditor account the\r\n        Confirmation of Payee discovery request carries.\r\n      additionalProperties: false\r\n      required: [Data]\r\n      properties:\r\n        Data:\r\n          type: object\r\n          additionalProperties: false\r\n          required: [IcpUserId]\r\n          properties:\r\n            IcpUserId:\r\n              $ref: '#/components/schemas/AEIcpUserId'\r\n\r\n    AEDiscoveredInstrument:\r\n      type: object\r\n      description: >-\r\n        An instrument the customer registered, as reported by discovery. The\r\n        discovery answer is deliberately narrower than the registration event:\r\n        it says what may be used and which is the default, and nothing else.\r\n      additionalProperties: false\r\n      required: [PaymentInstrument, Default]\r\n      properties:\r\n        PaymentInstrument:\r\n          $ref: '#/components/schemas/AEPaymentInstrument'\r\n        Default:\r\n          type: boolean\r\n          description: >-\r\n            Exactly one returned instrument is the default. Whether an initiator\r\n            may select a non-default instrument is an open item.\r\n\r\n    AEBiometricRegistrationSourceProperties:\r\n      type: object\r\n      description: >-\r\n        The resolved registration and the endpoints for acting on it. Mirrors\r\n        `AEConfirmationSourceProperties` in the Confirmation of Payee standard,\r\n        with the registration state and instruments added because BioPay\r\n        discovery answers two questions at once: where to go, and whether to go\r\n        at all.\r\n      additionalProperties: false\r\n      required: [IcpUserId, RegistrationStatus]\r\n      properties:\r\n        IcpUserId:\r\n          $ref: '#/components/schemas/AEIcpUserId'\r\n        RegistrationStatus:\r\n          $ref: '#/components/schemas/AERegistrationStatus'\r\n        DiscoveryEndpointUrl:\r\n          type: string\r\n          minLength: 1\r\n          maxLength: 500\r\n          description: >-\r\n            Discovery or .well-known endpoint hosted at the API Hub that\r\n            provides the information to request an Access Token from the target\r\n            LFI Authorisation Server. Present when `RegistrationStatus` is\r\n            `Registered`; absent otherwise.\r\n        ResourceServerUrl:\r\n          type: string\r\n          minLength: 1\r\n          maxLength: 500\r\n          description: >-\r\n            API Hub resource server URL at which the biometric payment\r\n            operation should be invoked for this registration. Present when\r\n            `RegistrationStatus` is `Registered`; absent otherwise. This\r\n            replaces the `LFIIdentification` the earlier draft returned — the\r\n            initiator is given the address rather than a code to build one from.\r\n        PaymentInstrument:\r\n          type: array\r\n          description: >-\r\n            The instruments available for this registration. Present when\r\n            `RegistrationStatus` is `Registered`; absent or empty otherwise.\r\n          items:\r\n            $ref: '#/components/schemas/AEDiscoveredInstrument'\r\n\r\n    AEBiometricRegistrationDiscoveryResponse:\r\n      type: object\r\n      description: The `message` of the signed discovery response.\r\n      additionalProperties: false\r\n      required: [Data]\r\n      properties:\r\n        Data:\r\n          $ref: '#/components/schemas/AEBiometricRegistrationSourceProperties'\r\n        Links:\r\n          $ref: '#/components/schemas/AELinks'\r\n        Meta:\r\n          $ref: '#/components/schemas/AEMeta'\r\n\r\n\r\n    AEBiometricRegistrationEventSigned:\r\n      type: object\r\n      description: >-\r\n        Signed event envelope, copied from `AEWebhookEventSigned` in the\r\n        published webhook template so that a BioPay event is verified exactly\r\n        like every other Open Finance webhook. `iss` is the API Hub. Note that\r\n        `aud` is an array here, where the discovery operation uses the\r\n        single-audience string form — that difference exists between the\r\n        published webhook and Confirmation of Payee standards and is carried\r\n        through rather than resolved by BioPay.\r\n      additionalProperties: false\r\n      required: [iss, exp, nbf, message]\r\n      properties:\r\n        iss:\r\n          type: string\r\n          description: '[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.1](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.1)'\r\n        exp:\r\n          type: number\r\n          description: '[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.4](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.4)'\r\n        nbf:\r\n          type: number\r\n          description: '[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.5](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.5)'\r\n        aud:\r\n          type: array\r\n          items:\r\n            type: string\r\n          description: '[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.3](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.3)'\r\n        iat:\r\n          type: number\r\n          description: '[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.6](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.6)'\r\n        message:\r\n          $ref: '#/components/schemas/AEBiometricRegistrationEvent'\r\n\r\n    AEBiometricRegistrationEvent:\r\n      type: object\r\n      description: >-\r\n        The `message` of the signed registration event. `Data` and `Meta` follow\r\n        the published webhook template: `Data` replicates the resource that\r\n        triggered the event — here, the same properties discovery returns — and\r\n        `Meta` describes the event itself. Only `Meta` is required, because the\r\n        template omits `Data` when `EventType` is `Resource.Deleted`.\r\n      additionalProperties: false\r\n      required: [Meta]\r\n      properties:\r\n        Data:\r\n          allOf:\r\n            - $ref: '#/components/schemas/AEBiometricRegistrationSourceProperties'\r\n          description: >-\r\n            The registration as it stands after the event, in the same shape the\r\n            discovery operation returns it. Omitted when `EventType` is\r\n            `Resource.Deleted`.\r\n        Meta:\r\n          type: object\r\n          additionalProperties: false\r\n          required: [EventDateTime, EventResource, EventType, RegistrationId]\r\n          properties:\r\n            EventDateTime:\r\n              type: string\r\n              format: date-time\r\n            EventResource:\r\n              type: string\r\n              description: >-\r\n                The resource that triggered the event. Open item: BioPay does not\r\n                expose the registration to the initiator as a fetchable resource\r\n                — discovery is the read path — so what this carries needs\r\n                deciding before the field is meaningful.\r\n              example: /biometric-payment-registrations/9f14c0e2-63b7-4a1c-9f2e-58b0d4a6c711\r\n            EventType:\r\n              type: string\r\n              description: >-\r\n                The webhook template's vocabulary, unchanged. A suspension or\r\n                revocation is a `Resource.Updated` whose `Data` carries the new\r\n                `RegistrationStatus`.\r\n              enum:\r\n                - Resource.Created\r\n                - Resource.Updated\r\n                - Resource.Deleted\r\n            RegistrationId:\r\n              type: string\r\n              minLength: 1\r\n              maxLength: 40\r\n              description: >-\r\n                The API Hub's identifier for the registration the event concerns.\r\n                Occupies the position `ConsentId` holds in the payment status\r\n                event, and is the only identifier present when `Data` is omitted.\r\n\r\n\r\n    AEBiometricAssurance:\r\n      type: object\r\n      description: >-\r\n        ICP's assertion about the identification it performed. This is the\r\n        evidence set for non-repudiation and dispute handling. It carries no\r\n        biometric data, no template and no match score.\r\n      additionalProperties: false\r\n      required: [MatchMethod, MatchDateTime, IcpTransactionId]\r\n      properties:\r\n        MatchMethod:\r\n          type: string\r\n          enum: [Fingerprint, FacialImage, Palm]\r\n        MatchDateTime:\r\n          type: string\r\n          format: date-time\r\n        IcpTransactionId:\r\n          type: string\r\n          description: ICP's own reference for the identification event.\r\n          maxLength: 40\r\n        AssuranceLevel:\r\n          type: string\r\n          description: Identity assurance level asserted by ICP. Vocabulary to be confirmed.\r\n\r\n    AEAmount:\r\n      type: object\r\n      additionalProperties: false\r\n      required: [Amount, Currency]\r\n      properties:\r\n        Amount:\r\n          type: string\r\n          pattern: '^\\d{1,13}\\.\\d{1,5}$'\r\n          example: '149.50'\r\n        Currency:\r\n          type: string\r\n          pattern: '^[A-Z]{3}$'\r\n          example: AED\r\n\r\n    AEAaniCreditor:\r\n      type: object\r\n      description: Creditor details for a payment executed over AANI.\r\n      additionalProperties: false\r\n      required: [CreditorType, CreditorAccount]\r\n      properties:\r\n        CreditorType:\r\n          type: string\r\n          enum: [AANI]\r\n        CreditorAccount:\r\n          type: object\r\n          additionalProperties: false\r\n          required: [SchemeName, Identification]\r\n          properties:\r\n            SchemeName:\r\n              type: string\r\n              enum: [IBAN, AANI.Alias, MobileNumber, EmiratesID]\r\n            Identification:\r\n              type: string\r\n              maxLength: 70\r\n              example: AE220331234567890876543\r\n            Name:\r\n              type: object\r\n              properties:\r\n                en: { type: string }\r\n                ar: { type: string }\r\n        CreditorAgent:\r\n          type: object\r\n          additionalProperties: false\r\n          properties:\r\n            SchemeName:\r\n              type: string\r\n              enum: [BICFI]\r\n            Identification:\r\n              type: string\r\n              example: BARBAEAAXXX\r\n\r\n    AEJaywanCreditor:\r\n      type: object\r\n      description: >-\r\n        Creditor details for a payment executed over the Jaywan domestic card\r\n        scheme. Field set is a first cut and needs validating against the\r\n        scheme's own message definition.\r\n      additionalProperties: false\r\n      required: [CreditorType, AcquirerIdentification, MerchantIdentification]\r\n      properties:\r\n        CreditorType:\r\n          type: string\r\n          enum: [JAYWAN]\r\n        AcquirerIdentification:\r\n          type: string\r\n          maxLength: 35\r\n        MerchantIdentification:\r\n          type: string\r\n          maxLength: 35\r\n        MerchantName:\r\n          type: string\r\n        TerminalIdentification:\r\n          type: string\r\n          maxLength: 35\r\n        SettlementAccount:\r\n          type: object\r\n          additionalProperties: false\r\n          properties:\r\n            SchemeName:\r\n              type: string\r\n              enum: [IBAN]\r\n            Identification:\r\n              type: string\r\n\r\n    AECbdcCreditor:\r\n      type: object\r\n      description: >-\r\n        Creditor details for a payment executed in Digital Dirham. Wallet\r\n        addressing is a placeholder pending the CBDC scheme definition.\r\n      additionalProperties: false\r\n      required: [CreditorType, CreditorWallet]\r\n      properties:\r\n        CreditorType:\r\n          type: string\r\n          enum: [CBDC]\r\n        CreditorWallet:\r\n          type: object\r\n          additionalProperties: false\r\n          required: [SchemeName, Identification]\r\n          properties:\r\n            SchemeName:\r\n              type: string\r\n              enum: [CBDC.WalletId]\r\n            Identification:\r\n              type: string\r\n              maxLength: 70\r\n            Name:\r\n              type: object\r\n              properties:\r\n                en: { type: string }\r\n                ar: { type: string }\r\n\r\n    AEBiometricPaymentRequest:\r\n      type: object\r\n      additionalProperties: false\r\n      required: [Data, Risk]\r\n      properties:\r\n        Data:\r\n          type: object\r\n          additionalProperties: false\r\n          required: [IcpUserId, PaymentInstrument, Instruction, Creditor, BiometricAssurance]\r\n          properties:\r\n            IcpUserId:\r\n              $ref: '#/components/schemas/AEIcpUserId'\r\n            PaymentInstrument:\r\n              $ref: '#/components/schemas/AEPaymentInstrument'\r\n            Instruction:\r\n              type: object\r\n              additionalProperties: false\r\n              required: [InstructionIdentification, EndToEndIdentification, InstructedAmount]\r\n              properties:\r\n                InstructionIdentification:\r\n                  type: string\r\n                  maxLength: 35\r\n                EndToEndIdentification:\r\n                  type: string\r\n                  maxLength: 35\r\n                InstructedAmount:\r\n                  $ref: '#/components/schemas/AEAmount'\r\n                RemittanceInformation:\r\n                  type: object\r\n                  additionalProperties: false\r\n                  properties:\r\n                    Reference:\r\n                      type: string\r\n                      maxLength: 35\r\n                    Unstructured:\r\n                      type: string\r\n                      maxLength: 140\r\n            Creditor:\r\n              description: >-\r\n                MUST match the `PaymentInstrument` named above, which in turn\r\n                MUST be one the discovery response listed for a registration\r\n                whose `RegistrationStatus` is `Registered`.\r\n              oneOf:\r\n                - $ref: '#/components/schemas/AEAaniCreditor'\r\n                - $ref: '#/components/schemas/AEJaywanCreditor'\r\n                - $ref: '#/components/schemas/AECbdcCreditor'\r\n              discriminator:\r\n                propertyName: CreditorType\r\n                mapping:\r\n                  AANI: '#/components/schemas/AEAaniCreditor'\r\n                  JAYWAN: '#/components/schemas/AEJaywanCreditor'\r\n                  CBDC: '#/components/schemas/AECbdcCreditor'\r\n            BiometricAssurance:\r\n              $ref: '#/components/schemas/AEBiometricAssurance'\r\n        Risk:\r\n          type: object\r\n          additionalProperties: false\r\n          required: [PaymentContextCode]\r\n          properties:\r\n            PaymentContextCode:\r\n              type: string\r\n              enum: [BiometricPointOfSale, BiometricUnattendedTerminal]\r\n            MerchantCategoryCode:\r\n              type: string\r\n              pattern: '^\\d{4}$'\r\n              example: '5411'\r\n            MerchantIdentification:\r\n              type: string\r\n              maxLength: 35\r\n            MerchantName:\r\n              type: string\r\n            TerminalIdentification:\r\n              type: string\r\n              maxLength: 35\r\n\r\n    AERailReference:\r\n      type: object\r\n      description: >-\r\n        How the payment was represented on the rail that executed it. Populated\r\n        by the LFI once the rail has responded.\r\n      additionalProperties: false\r\n      properties:\r\n        Scheme:\r\n          $ref: '#/components/schemas/AEPaymentInstrument'\r\n        SchemeTransactionId:\r\n          type: string\r\n          maxLength: 70\r\n        SchemeStatus:\r\n          type: string\r\n          description: >-\r\n            The rail's own status value, carried through unmapped for\r\n            reconciliation. The normalised value is `Status`.\r\n\r\n    AEBiometricPayment:\r\n      type: object\r\n      additionalProperties: false\r\n      required: [PaymentId, Status, CreationDateTime, StatusUpdateDateTime]\r\n      properties:\r\n        PaymentId:\r\n          type: string\r\n          maxLength: 40\r\n        IdempotencyKey:\r\n          type: string\r\n          maxLength: 40\r\n        Status:\r\n          $ref: '#/components/schemas/AEPaymentStatus'\r\n        CreationDateTime:\r\n          type: string\r\n          format: date-time\r\n        StatusUpdateDateTime:\r\n          type: string\r\n          format: date-time\r\n        IcpUserId:\r\n          $ref: '#/components/schemas/AEIcpUserId'\r\n        LFIIdentification:\r\n          type: string\r\n          example: altareq1\r\n        PaymentInstrument:\r\n          $ref: '#/components/schemas/AEPaymentInstrument'\r\n        Instruction:\r\n          type: object\r\n          description: Echo of the submitted instruction.\r\n          additionalProperties: true\r\n        RailReference:\r\n          $ref: '#/components/schemas/AERailReference'\r\n        StatusReason:\r\n          $ref: '#/components/schemas/AEBiometricPaymentStatusReason'\r\n\r\n    AEBiometricPaymentStatusReason:\r\n      type: object\r\n      description: >-\r\n        Why a payment ended where it did. Set by the LFI on the payment log\r\n        patch and served back unchanged on the payment resource.\r\n      additionalProperties: false\r\n      properties:\r\n        Code:\r\n          type: string\r\n        Description:\r\n          type: string\r\n\r\n    AEBiometricPaymentLogPatch:\r\n      type: object\r\n      description: >-\r\n        The fields an LFI may set on a biometric payment after creation. Only\r\n        the status and what qualifies it: the instruction, the creditor and the\r\n        biometric assurance were fixed when the payment was created and cannot\r\n        be patched.\r\n      additionalProperties: false\r\n      required: [Status]\r\n      properties:\r\n        Status:\r\n          $ref: '#/components/schemas/AEPaymentStatus'\r\n        StatusUpdateDateTime:\r\n          type: string\r\n          format: date-time\r\n          description: >-\r\n            When the LFI observed this status. The Hub records its own receipt\r\n            time where this is omitted.\r\n        RailReference:\r\n          $ref: '#/components/schemas/AERailReference'\r\n        StatusReason:\r\n          description: >-\r\n            MUST be present when `Status` is `Rejected`, carrying the reason\r\n            the initiator needs in order to tell the customer whether another\r\n            attempt is worthwhile.\r\n          allOf:\r\n            - $ref: '#/components/schemas/AEBiometricPaymentStatusReason'\r\n\r\n    AEBiometricPaymentResponse:\r\n      type: object\r\n      additionalProperties: false\r\n      required: [Data]\r\n      properties:\r\n        Data:\r\n          $ref: '#/components/schemas/AEBiometricPayment'\r\n        Links:\r\n          $ref: '#/components/schemas/AELinks'\r\n        Meta:\r\n          $ref: '#/components/schemas/AEMeta'\r\n\r\n    AEBiometricPaymentQueryResponse:\r\n      type: object\r\n      description: >-\r\n        Query result shape. `Data` holds zero or one payment — an empty array\r\n        means no payment was created for that idempotency key.\r\n      additionalProperties: false\r\n      required: [Data]\r\n      properties:\r\n        Data:\r\n          type: array\r\n          maxItems: 1\r\n          items:\r\n            $ref: '#/components/schemas/AEBiometricPayment'\r\n        Links:\r\n          $ref: '#/components/schemas/AELinks'\r\n        Meta:\r\n          $ref: '#/components/schemas/AEMeta'\r\n\r\n    # ── Signed JWT envelopes ───────────────────────────────────────────────\r\n    # Claim set and required fields are copied from the Confirmation of Payee\r\n    # standard's *BodySigned schemas so the two discovery operations are signed\r\n    # and verified the same way. `message` holds the payload; `iss` is the\r\n    # signer, and the initiator verifies the response against the API Hub's\r\n    # signing key published at its JWKS endpoint.\r\n\r\n    DiscoverBiometricRegistrationRequestBodySigned:\r\n      type: object\r\n      description: Signed by the initiator (ICP) and sent as `application/jwt`.\r\n      additionalProperties: false\r\n      required: [iss, exp, nbf, message]\r\n      properties:\r\n        iss:\r\n          type: string\r\n          description: '[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.1](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.1)'\r\n        exp:\r\n          type: number\r\n          description: '[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.4](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.4)'\r\n        nbf:\r\n          type: number\r\n          description: '[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.5](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.5)'\r\n        aud:\r\n          type: string\r\n          description: >-\r\n            The identifier of the intended recipient of the JWT. A single\r\n            StringOrURI per RFC 7519 §4.1.3 (single-audience form).\r\n            [https://www.rfc-editor.org/rfc/rfc7519#section-4.1.3](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.3)\r\n        iat:\r\n          type: number\r\n          description: '[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.6](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.6)'\r\n        message:\r\n          $ref: '#/components/schemas/AEBiometricDiscoveryRequest'\r\n\r\n    DiscoverBiometricRegistrationResponseBodySigned:\r\n      type: object\r\n      description: Signed by the API Hub and returned as `application/jwt`.\r\n      additionalProperties: false\r\n      required: [iss, exp, nbf, message]\r\n      properties:\r\n        iss:\r\n          type: string\r\n          description: '[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.1](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.1)'\r\n        exp:\r\n          type: number\r\n          description: '[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.4](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.4)'\r\n        nbf:\r\n          type: number\r\n          description: '[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.5](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.5)'\r\n        aud:\r\n          type: string\r\n          description: >-\r\n            The identifier of the intended recipient of the JWT. A single\r\n            StringOrURI per RFC 7519 §4.1.3 (single-audience form).\r\n            [https://www.rfc-editor.org/rfc/rfc7519#section-4.1.3](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.3)\r\n        iat:\r\n          type: number\r\n          description: '[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.6](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.6)'\r\n        message:\r\n          $ref: '#/components/schemas/AEBiometricRegistrationDiscoveryResponse'\r\n\r\n    AEErrorResponseBodySigned:\r\n      type: object\r\n      description: >-\r\n        Signed error body, returned as `application/jwt` by operations whose\r\n        success responses are signed. Operations with unsigned JSON responses\r\n        return `AEErrorResponse` directly.\r\n      additionalProperties: false\r\n      required: [iss, exp, nbf, message]\r\n      properties:\r\n        iss:\r\n          type: string\r\n          description: '[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.1](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.1)'\r\n        exp:\r\n          type: number\r\n          description: '[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.4](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.4)'\r\n        nbf:\r\n          type: number\r\n          description: '[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.5](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.5)'\r\n        aud:\r\n          type: string\r\n          description: >-\r\n            The identifier of the intended recipient of the JWT. A single\r\n            StringOrURI per RFC 7519 §4.1.3 (single-audience form).\r\n            [https://www.rfc-editor.org/rfc/rfc7519#section-4.1.3](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.3)\r\n        iat:\r\n          type: number\r\n          description: '[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.6](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.6)'\r\n        message:\r\n          $ref: '#/components/schemas/AEErrorResponse'\r\n\r\n\r\n    AELinks:\r\n      type: object\r\n      additionalProperties: false\r\n      required: [Self]\r\n      properties:\r\n        Self:\r\n          type: string\r\n          format: uri\r\n\r\n    AEMeta:\r\n      type: object\r\n      additionalProperties: false\r\n      properties:\r\n        TotalPages:\r\n          type: integer\r\n\r\n    AEErrorResponse:\r\n      type: object\r\n      additionalProperties: false\r\n      required: [Code, Errors]\r\n      properties:\r\n        Code:\r\n          type: string\r\n        Id:\r\n          type: string\r\n          description: Correlates to `x-fapi-interaction-id`.\r\n        Message:\r\n          type: string\r\n        Errors:\r\n          type: array\r\n          minItems: 1\r\n          items:\r\n            type: object\r\n            additionalProperties: false\r\n            required: [ErrorCode]\r\n            properties:\r\n              ErrorCode:\r\n                type: string\r\n              Message:\r\n                type: string\r\n              Path:\r\n                type: string\r\n";
